-- المرحلة الثانية: جداول الإدارة والوسائط. شغّلها مرة واحدة في Supabase SQL Editor.
create table if not exists public.media (id uuid primary key default gen_random_uuid(), url text not null, storage_path text, alt_text text, caption text, category text default 'general', created_at timestamptz default now(), updated_at timestamptz default now(), deleted_at timestamptz);
create table if not exists public.sliders (id uuid primary key default gen_random_uuid(), title_ar text, description_ar text, image_url text, button_text_ar text, button_url text, sort_order int default 0, is_published boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.working_hours (id bigint generated by default as identity primary key, day_key text unique not null, label_ar text not null, morning_from time, morning_to time, evening_from time, evening_to time, is_closed boolean default false, sort_order int default 0, updated_at timestamptz default now());
create table if not exists public.social_links (id bigint generated by default as identity primary key, platform text unique not null, url text not null, is_published boolean default true, sort_order int default 0, updated_at timestamptz default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), title_ar text not null, event_date date, place_ar text, description_ar text, cover_url text, video_url text, status text default 'past' check(status in ('upcoming','current','past')), is_published boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
insert into public.working_hours(day_key,label_ar,morning_from,morning_to,evening_from,evening_to,is_closed,sort_order) values
('sat','السبت','09:00','14:00','16:00','21:00',false,1),('sun','الأحد','09:00','14:00','16:00','21:00',false,2),('mon','الاثنين','09:00','14:00','16:00','21:00',false,3),('tue','الثلاثاء','09:00','14:00','16:00','21:00',false,4),('wed','الأربعاء','09:00','14:00','16:00','21:00',false,5),('thu','الخميس','09:00','14:00','16:00','21:00',false,6),('fri','الجمعة',null,null,null,null,true,7) on conflict(day_key) do nothing;
insert into public.social_links(platform,url,sort_order) values ('facebook','https://www.facebook.com/Dr.Abdulbaset.clinic',1),('youtube','https://youtube.com/@dr.abdulbaset_clinic?si=IYsRFIycho-GM1yV',2),('instagram','https://www.instagram.com/almamooncenter?stkn=YzByaTI5dTVwMnJr',3) on conflict(platform) do nothing;
alter table public.media enable row level security; alter table public.sliders enable row level security; alter table public.working_hours enable row level security; alter table public.social_links enable row level security; alter table public.events enable row level security;
do $$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='working_hours' and policyname='public read working hours') then create policy "public read working hours" on public.working_hours for select using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='social_links' and policyname='public read social links') then create policy "public read social links" on public.social_links for select using(is_published=true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='events' and policyname='public read events') then create policy "public read events" on public.events for select using(is_published=true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='sliders' and policyname='public read sliders') then create policy "public read sliders" on public.sliders for select using(is_published=true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='media' and policyname='public read media') then create policy "public read media" on public.media for select using(deleted_at is null); end if;
end $$;
-- سياسات الكتابة يجب أن تُربط بأدوار profiles الموجودة في مشروعك قبل استخدام لوحة الإدارة في الإنتاج.
